create table if not exists public.ssc_notices(id bigint generated by default as identity primary key,title text not null,notice_date date,file_path text,file_size text,created_at timestamptz not null default now());
alter table public.ssc_notices enable row level security;
drop policy if exists "Public can read notices" on public.ssc_notices;
create policy "Public can read notices" on public.ssc_notices for select to anon,authenticated using(true);
drop policy if exists "Authenticated admins can insert notices" on public.ssc_notices;
create policy "Authenticated admins can insert notices" on public.ssc_notices for insert to authenticated with check(true);
insert into storage.buckets(id,name,public) values('ssc-files','ssc-files',true) on conflict(id) do update set public=true;
drop policy if exists "Authenticated users can upload SSC files" on storage.objects;
create policy "Authenticated users can upload SSC files" on storage.objects for insert to authenticated with check(bucket_id='ssc-files');
drop policy if exists "Public can read SSC files" on storage.objects;
create policy "Public can read SSC files" on storage.objects for select to anon,authenticated using(bucket_id='ssc-files');